    byte[] buffer = new byte[STREAM_BUFFER_LENGTH];
    int read = data.read(buffer, 0, STREAM_BUFFER_LENGTH);

    while (read > -1) {
        digest.update(buffer, 0, read);
        read = data.read(buffer, 0, STREAM_BUFFER_LENGTH);
    }

